94: 
95:     const int maxOpenFiles = 4;
96:     s_spiffsWorkBuf.resize(s_pageSize * 2);
97:     s_spiffsFds.resize(32 * maxOpenFiles);
98:     s_spiffsCache.resize((32 + s_pageSize) * maxOpenFiles);
