140: int addFile(char* name, const char* path)
141: {
142:     FILE* src = fopen(path, "rb");
143:     if (!src) {
144:         std::cerr << "error: failed to open " << path << " for reading" << std::endl;
145:         return 1;
146:     }
147: 
148:     spiffs_file dst = SPIFFS_open(&s_fs, name, SPIFFS_CREAT | SPIFFS_TRUNC | SPIFFS_RDWR, 0);
149: 
150:     // read file size
151:     size_t size = getFileSize(src);
152: 
153:     if (s_debugLevel > 0) {
154:         std::cout << "file size: " << size << std::endl;
155:     }
156: 
157:     size_t left = size;
158:     uint8_t data_byte;
159:     while (left > 0) {
160:         if (1 != fread(&data_byte, 1, 1, src)) {
161:             std::cerr << "fread error!" << std::endl;
162: 
163:             fclose(src);
164:             SPIFFS_close(&s_fs, dst);
165:             return 1;
166:         }
167:         int res = SPIFFS_write(&s_fs, dst, &data_byte, 1);
168:         if (res < 0) {
169:             std::cerr << "SPIFFS_write error(" << s_fs.err_code << "): ";
170: 
171:             if (s_fs.err_code == SPIFFS_ERR_FULL) {
172:                 std::cerr << "File system is full." << std::endl;
173:             } else {
174:                 std::cerr << "unknown";
175:             }
176:             std::cerr << std::endl;
177: 
178:             if (s_debugLevel > 0) {
179:                 std::cout << "data left: " << left << std::endl;
180:             }
181: 
182:             fclose(src);
183:             SPIFFS_close(&s_fs, dst);
184:             return 1;
185:         }
186:         left -= 1;
187:     }
188: 
189:     SPIFFS_close(&s_fs, dst);
190:     fclose(src);
191: 
192:     return 0;
193: }
