195: int addFiles(const char* dirname, const char* subPath)
196: {
197:     DIR *dir;
198:     struct dirent *ent;
199:     bool error = false;
200:     std::string dirPath = dirname;
201:     dirPath += subPath;
202: 
203:     // Open directory
204:     if ((dir = opendir (dirPath.c_str())) != NULL) {
205: 
206:         // Read files from directory.
207:         while ((ent = readdir (dir)) != NULL) {
208: 
209:             // Ignore dir itself.
210:             if ((strcmp(ent->d_name, ".") == 0) || (strcmp(ent->d_name, "..") == 0)) {
211:                 continue;
212:             }
213: 
214:             if (!s_addAllFiles) {
215:                 bool skip = false;
216:                 size_t ignored_file_names_count = sizeof(ignored_file_names) / sizeof(ignored_file_names[0]);
217:                 for (size_t i = 0; i < ignored_file_names_count; ++i) {
218:                     if (strcmp(ent->d_name, ignored_file_names[i]) == 0) {
219:                         std::cerr << "skipping " << ent->d_name << std::endl;
220:                         skip = true;
221:                         break;
222:                     }
223:                 }
224:                 if (skip) {
225:                     continue;
226:                 }
227:             }
228: 
229:             std::string fullpath = dirPath;
230:             fullpath += ent->d_name;
231:             struct stat path_stat;
232:             stat (fullpath.c_str(), &path_stat);
233: 
234:             if (!S_ISREG(path_stat.st_mode)) {
235:                 // Check if path is a directory.
236:                 if (S_ISDIR(path_stat.st_mode)) {
237:                     // Prepare new sub path.
238:                     std::string newSubPath = subPath;
239:                     newSubPath += ent->d_name;
240:                     newSubPath += "/";
241: 
242:                     if (addFiles(dirname, newSubPath.c_str()) != 0) {
243:                         std::cerr << "Error for adding content from " << ent->d_name << "!" << std::endl;
244:                     }
245: 
246:                     continue;
247:                 } else {
248:                     std::cerr << "skipping " << ent->d_name << std::endl;
249:                     continue;
250:                 }
251:             }
252: 
253:             // Filepath with dirname as root folder.
254:             std::string filepath = subPath;
255:             filepath += ent->d_name;
256:             std::cout << filepath << std::endl;
257: 
258:             // Add File to image.
259:             if (addFile((char*)filepath.c_str(), fullpath.c_str()) != 0) {
260:                 std::cerr << "error adding file!" << std::endl;
261:                 error = true;
262:                 if (s_debugLevel > 0) {
263:                     std::cout << std::endl;
264:                 }
265:                 break;
266:             }
267:         } // end while
268:         closedir (dir);
269:     } else {
270:         std::cerr << "warning: can't read source directory" << std::endl;
271:         return 1;
272:     }
273: 
274:     return (error) ? 1 : 0;
275: }
