376: /**
377:  * @brief Unpack files from file system.
378:  * @param sDest Directory path as std::string.
379:  * @return True or false.
380:  *
381:  * @author Pascal Gollor (http://www.pgollor.de/cms/)
382:  *
383:  * todo: Do unpack stuff for directories.
384:  */
385: bool unpackFiles(std::string sDest)
386: {
387:     spiffs_DIR dir;
388:     spiffs_dirent ent;
389: 
390:     // Add "./" to path if is not given.
391:     if (sDest.find("./") == std::string::npos && sDest.find("/") == std::string::npos) {
392:         sDest = "./" + sDest;
393:     }
394: 
395:     // Check if directory exists. If it does not then try to create it with permissions 755.
396:     if (! dirExists(sDest.c_str())) {
397:         std::cout << "Directory " << sDest << " does not exists. Try to create it." << std::endl;
398: 
399:         // Try to create directory.
400:         if (! dirCreate(sDest.c_str())) {
401:             return false;
402:         }
403:     }
404: 
405:     // Open directory.
406:     SPIFFS_opendir(&s_fs, 0, &dir);
407: 
408:     // Read content from directory.
409:     spiffs_dirent* it = SPIFFS_readdir(&dir, &ent);
410:     while (it) {
411:         // Check if content is a file.
412:         if ((int)(it->type) == 1) {
413:             std::string name = (const char*)(it->name);
414:             std::string sDestFilePath = sDest + name;
415:             size_t pos = name.find_first_of("/", 1);
416: 
417:             // If file is in sub directories?
418:             while (pos != std::string::npos) {
419:                 // Subdir path.
420:                 std::string path = sDest;
421:                 path += name.substr(0, pos);
422: 
423:                 // Create subddir if subdir not exists.
424:                 if (!dirExists(path.c_str())) {
425:                     if (!dirCreate(path.c_str())) {
426:                         return false;
427:                     }
428:                 }
429: 
430:                 pos = name.find_first_of("/", pos + 1);
431:             }
432: 
433:             // Unpack file to destination directory.
434:             if (! unpackFile(it, sDestFilePath.c_str()) ) {
435:                 std::cout << "Can not unpack " << it->name << "!" << std::endl;
436:                 return false;
437:             }
438: 
439:             // Output stuff.
440:             std::cout
441:                     << it->name
442:                     << '\t'
443:                     << " > " << sDestFilePath
444:                     << '\t'
445:                     << "size: " << it->size << " Bytes"
446:                     << std::endl;
447:         }
448: 
449:         // Get next file handle.
450:         it = SPIFFS_readdir(&dir, &ent);
451:     } // end while
452: 
453:     // Close directory.
454:     SPIFFS_closedir(&dir);
455: 
456:     return true;
457: }
