657: void processArgs(int argc, const char** argv)
658: {
659:     TCLAP::CmdLine cmd("", ' ', VERSION);
660:     CustomOutput output;
661:     cmd.setOutput(&output);
662: 
663:     TCLAP::ValueArg<std::string> packArg( "c", "create", "create spiffs image from a directory", true, "", "pack_dir");
664:     TCLAP::ValueArg<std::string> unpackArg( "u", "unpack", "unpack spiffs image to a directory", true, "", "dest_dir");
665:     TCLAP::SwitchArg listArg( "l", "list", "list files in spiffs image", false);
666:     TCLAP::SwitchArg visualizeArg( "i", "visualize", "visualize spiffs image", false);
667:     TCLAP::UnlabeledValueArg<std::string> outNameArg( "image_file", "spiffs image file", true, "", "image_file"  );
668:     TCLAP::ValueArg<int> imageSizeArg( "s", "size", "fs image size, in bytes", false, 0, "number" );
669:     TCLAP::ValueArg<int> pageSizeArg( "p", "page", "fs page size, in bytes", false, 256, "number" );
